{"command": "python - <<'PY'
import numpy as np, warnings
from sklearn.base import BaseEstimator, ClassifierMixin
from sklearn.linear_model import LogisticRegression
from sklearn.calibration import CalibratedClassifierCV

class RecordingClassifier(ClassifierMixin, BaseEstimator):
    def __init__(self, fit_param=None):
        self.fit_param = fit_param
    def fit(self, X, y, sample_weight=None):
        self.fit_param_ = self.fit_param
        self.sample_weight_ = None if sample_weight is None else np.asarray(sample_weight).copy()
        self._clf = LogisticRegression(max_iter=1000).fit(X, y, sample_weight=sample_weight)
        self.classes_ = self._clf.classes_
        return self
    def predict_proba(self, X):
        return self._clf.predict_proba(X)
    def predict(self, X):
        return self._clf.predict(X)

class NoWeightClassifier(ClassifierMixin, BaseEstimator):
    def fit(self, X, y, custom_param=None):
        self.custom_param_ = custom_param
        self._clf = LogisticRegression(max_iter=1000).fit(X,y)
        self.classes_ = self._clf.classes_
        return self
    def predict_proba(self,X): return self._clf.predict_proba(X)
    def predict(self,X): return self._clf.predict(X)

from sklearn.datasets import make_classification
X,y=make_classification(n_samples=60,n_features=5,n_informative=3,n_redundant=0,random_state=0)
sw=np.linspace(0.5,2,len(y))
c=CalibratedClassifierCV(RecordingClassifier(), cv=3, ensemble=False).fit(X,y,sample_weight=sw)
print('sw', c.calibrated_classifiers_[0].estimator.sample_weight_, len(c.calibrated_classifiers_))
with warnings.catch_warnings(record=True) as ws:
 warnings.simplefilter('always')
 c=CalibratedClassifierCV(NoWeightClassifier(), cv=3, ensemble=False).fit(X,y,sample_weight=sw,custom_param='foo')
 print('warning', [(str(w.message),w.category) for w in ws])
print('custom',c.calibrated_classifiers_[0].estimator.custom_param_)
PY"}

