{"command": "python - <<'PY'
import numpy as np, traceback
from sklearn.cluster import ward_tree
X=np.array([[0.,0.],[1.,0.],[0.,1.]])
cases = [
 ('return_distance', dict(return_distance='yes')),
 ('n_clusters0', dict(n_clusters=0)),
 ('n_clustersfloat', dict(n_clusters=1.5)),
 ('Xstring', None),
 ('connectivitystring', dict(connectivity='bad')),
]
for name,kw in cases:
    try:
        if name=='Xstring': ward_tree('bad')
        else: ward_tree(X, **kw)
    except Exception as e:
        print(name, type(e).__module__, type(e).__name__, str(e)[:500])
    else: print(name,'NO ERROR')
# list conn
conn=[[0,1,1],[1,0,1],[1,1,0]]
try:
    print(ward_tree(X, connectivity=conn))
except Exception as e:
    print('list conn',type(e).__name__,str(e)[:300])
# mismatch
try:
    print(ward_tree(X, connectivity=np.ones((2,2))))
except Exception as e:
    print('mismatch',type(e).__name__,str(e)[:300])
# nc>samples with conn
try:
    print(ward_tree(X, connectivity=np.ones((3,3))-np.eye(3), n_clusters=4))
except Exception as e:
    print('nc>',type(e).__name__,str(e)[:300])
# nc None connectivity, nc>n
import warnings
with warnings.catch_warnings(record=True) as w:
    warnings.simplefilter('always')
    out=ward_tree(X,n_clusters=5)
    print('nc> n no conn out', out)
    print('warnings',[(type(x.message).__name__,str(x.message)[:100]) for x in w])
PY"}

