X=np.array([[0.,0.],[0.,1.],[1.,0.],[1.,1.],[10.,10.],[10.,11.],[11.,10.],[11.,11.]])
D=pairwise_distances(X)
for inp in [D, sparse.csr_matrix(D), sparse.lil_matrix(D)]:
