"""Unit tests for ``BaseForest.fit`` (sklearn.ensemble._forest)."""

import numpy as np
import pytest
from scipy import sparse

from sklearn.ensemble import (
    ExtraTreesClassifier,
    ExtraTreesRegressor,
    RandomForestClassifier,
    RandomForestRegressor,
)
from sklearn.exceptions import DataConversionWarning, InvalidParameterError
from sklearn.utils.validation import check_is_fitted

FOREST_CLASSIFIERS = [RandomForestClassifier, ExtraTreesClassifier]
FOREST_REGRESSORS = [RandomForestRegressor, ExtraTreesRegressor]
ALL_FORESTS = FOREST_CLASSIFIERS + FOREST_REGRESSORS


def is_classifier_cls(cls):
    return cls in FOREST_CLASSIFIERS


def make_regression_data(n_samples=40, n_features=3, n_outputs=None, seed=0):
    rng = np.random.RandomState(seed)
    X = rng.rand(n_samples, n_features)
    y = X[:, 0] + 0.1 * rng.rand(n_samples)
    if n_outputs is not None:
        y = np.column_stack([y + k for k in range(n_outputs)])
    return X, y


def make_classification_data(n_samples=40, n_features=3, n_classes=3, seed=0):
    rng = np.random.RandomState(seed)
    X = rng.rand(n_samples, n_features)
    y = rng.randint(0, n_classes, size=n_samples)
    return X, y


def make_multilabel_data(n_samples=40, n_features=3, n_labels=3, seed=0):
    rng = np.random.RandomState(seed)
    X = rng.rand(n_samples, n_features)
    y = rng.randint(0, 2, size=(n_samples, n_labels))
    return X, y


def fit_forest(forest_cls, X, y, **kwargs):
    params = {"n_estimators": 5, "random_state": 0}
    params.update(kwargs)
    return forest_cls(**params)


