    X, y = make_regression_data(n_outputs=2)
    assert y.ndim == 2 and y.shape[1] == 2

    with pytest.warns(None) if False else _no_warnings() as record:
        forest = fit_forest(forest_cls, X, y).fit(X, y)

    assert not [w for w in record if issubclass(w.category, DataConversionWarning)]
    assert forest.n_outputs_ == 2
    assert forest.predict(X).shape == (X.shape[0], 2)


