@pytest.mark.parametrize("forest_cls", ALL_FORESTS)
def test_fit_sparse_input_with_unsorted_indices(forest_cls):
    if is_classifier_cls(forest_cls):
        X, y = make_classification_data(n_classes=2)
    else:
        X, y = make_regression_data()
    X = np.abs(X) + 0.1
    # Build a CSC matrix whose row indices are not sorted within each column.
    indptr = np.arange(0, (X.shape[0] + 1) * X.shape[1], X.shape[0])
    indices = np.tile(np.arange(X.shape[0] - 1, -1, -1), X.shape[1])
    data = X.T.ravel()
    X_unsorted = sparse.csc_matrix(
        (data, indices, indptr), shape=(X.shape[0], X.shape[1])
    )
    assert not X_unsorted.has_sorted_indices

    forest = fit_forest(forest_cls, X, y).fit(X_unsorted, y)

    check_is_fitted(forest)
    assert forest.n_features_in_ == X.shape[1]
    assert np.all(np.isfinite(forest.predict(X_unsorted)))


