class _no_warnings:
    """Context manager collecting warnings without failing on them."""

    def __enter__(self):
        self._cm = warnings_catch(record=True)
        self._record = self._cm.__enter__()
        return self._record

    def __exit__(self, *exc_info):
        return self._cm.__exit__(*exc_info)


