import numpy as np
from sklearn.base import BaseEstimator, RegressorMixin
from sklearn.linear_model import RANSACRegressor

class Rec(BaseEstimator, RegressorMixin):
    def __init__(self, records=None):
        self.records=records
    def fit(self, X, y, sample_weight=None):
        self.records.append((X.shape, np.asarray(y).shape, None if sample_weight is None else np.asarray(sample_weight).shape))
        self.mean_=float(np.mean(y))
        return self
    def predict(self, X):
        return np.full(np.asarray(X).shape[0], self.mean_)
    def score(self, X, y):
        return 1.0

records=[]
X=np.arange(20).reshape(10,2).astype(float); y=np.arange(10).astype(float)
r=RANSACRegressor(estimator=Rec(records=records), min_samples=2, residual_threshold=np.inf, random_state=0)
out=r.fit(X,y,sample_weight=np.ones(10))
print(out, records, out.inlier_mask_, out.n_trials_)

class NoSW(BaseEstimator, RegressorMixin):
    def fit(self, X,y): self.mean_=float(np.mean(y)); return self
    def predict(self,X): return np.full(len(X), self.mean_)
    def score(self,X,y): return 1.0
try:
    RANSACRegressor(estimator=NoSW(), min_samples=2).fit(X,y,sample_weight=np.ones(10))
except Exception as e:
    print(type(e),e)
