import numpy as np
from sklearn.base import BaseEstimator
from sklearn.datasets import make_classification
from sklearn.model_selection import learning_curve
X, y = make_classification(n_samples=40, n_features=4, random_state=0)

class Counting(BaseEstimator):
    def __init__(self):
        pass
    def fit(self, X, y=None):
        self.n_fit_ = len(X)
        return self
    def partial_fit(self, X, y=None, classes=None):
        self.n_partial_ = getattr(self, "n_partial_", 0) + len(X)
        return self
    def predict(self, X):
        return np.zeros(len(X))
    def score(self, X, y):
        return 1.0

out = learning_curve(Counting(), X, y, train_sizes=[0.5, 1.0], cv=2, exploit_incremental_learning=True)
print([o.shape for o in out])
print(out[1], out[2])

class Recorder(BaseEstimator):
    def fit(self, X, y=None):
        self.sum_ = float(np.sum(X))
        return self
    def predict(self, X):
        return np.zeros(len(X))
    def score(self, X, y):
        return 1.0

# record via global
seen = []
class Rec2(BaseEstimator):
    def fit(self, X, y=None):
        seen.append(float(np.sum(X)))
        return self
    def predict(self, X):
        return np.zeros(len(X))
    def score(self, X, y):
        return 1.0
a = learning_curve(Rec2(), X, y, train_sizes=[0.5], cv=2)
s1 = list(seen)
seen.clear()
b = learning_curve(Rec2(), X, y, train_sizes=[0.5], cv=2, shuffle=True, random_state=0)
s2 = list(seen)
seen.clear()
c = learning_curve(Rec2(), X, y, train_sizes=[0.5], cv=2, shuffle=True, random_state=0)
