"""Tests for :func:`sklearn.preprocessing.label_binarize`."""

import numpy as np
import pytest
from scipy import sparse as sp

from sklearn.preprocessing import label_binarize
from sklearn.utils._param_validation import InvalidParameterError


def _dense(array):
    """Return a dense ndarray for a possibly sparse result."""
    if sp.issparse(array):
        return array.toarray()
    return np.asarray(array)


def test_multiclass_numeric_labels_documented_example():
    result = label_binarize([1, 6], classes=[1, 2, 4, 6])

    assert isinstance(result, np.ndarray)
    assert result.shape == (2, 4)
    np.testing.assert_array_equal(
        result,
        np.array(
            [
                [1, 0, 0, 0],
                [0, 0, 0, 1],
            ]
        ),
    )


@pytest.mark.parametrize(
    "classes, expected",
    [
        (
            [1, 6, 4, 2],
            [
                [1, 0, 0, 0],
                [0, 1, 0, 0],
            ],
        ),
        (
            [4, 2, 1, 6],
            [
                [0, 0, 1, 0],
                [1, 0, 0, 0],
            ],
        ),
        (
            [6, 4, 2, 1],
            [
                [0, 0, 0, 1],
                [1, 0, 0, 0],
            ],
        ),
    ],
)
def test_multiclass_output_preserves_class_order(classes, expected):
    result = label_binarize([1, 6], classes=classes)

    np.testing.assert_array_equal(result, np.asarray(expected))


@pytest.mark.parametrize(
    "classes, expected",
    [
