    y = ["yes", "no", "no", "yes"]

    result = label_binarize(y, classes=classes)

    assert result.shape == (4, 1)
    np.testing.assert_array_equal(result, np.asarray(expected))


def test_binary_column_input_returns_a_single_column():
    y = np.array([[0], [1], [1], [0]])

