import numpy as np
from sklearn.base import BaseEstimator, ClassifierMixin
from sklearn.utils.estimator_checks import check_classifiers_train


class BaseDummy(ClassifierMixin, BaseEstimator):
    def __init__(self, random_state=None):
        self.random_state = random_state

    def fit(self, X, y, sample_weight=None):
        X = np.asarray(X, dtype=np.float64)
        y = np.asarray(y)
        if X.ndim != 2:
            raise ValueError("X ndim")
        if X.shape[0] != y.shape[0]:
            raise ValueError("inconsistent numbers of samples")
        self.classes_ = np.unique(y)
        self.n_features_in_ = X.shape[1]
        self._centroids_ = np.stack([X[y == c].mean(axis=0) for c in self.classes_])
        return self

    def _scores(self, X):
        X = np.asarray(X, dtype=np.float64)
        if X.ndim != 2 or X.shape[1] != self.n_features_in_:
            raise ValueError(
                f"X has {X.shape[1] if X.ndim == 2 else 'invalid'} features, "
                f"but {type(self).__name__} is expecting {self.n_features_in_} features"
            )
        d = X[:, None, :] - self._centroids_[None, :, :]
        return -(d**2).sum(axis=2)

    def decision_function(self, X):
        s = self._scores(X)
        if self.classes_.size == 2:
            return s[:, 1] - s[:, 0]
        return s

    def predict(self, X):
        return self.classes_[np.argmax(self._scores(X), axis=1)]

    def predict_proba(self, X):
        s = self._scores(X)
        s = s - s.max(axis=1, keepdims=True)
        e = np.exp(s)
        return e / e.sum(axis=1, keepdims=True)

    def predict_log_proba(self, X):
        return np.log(self.predict_proba(X))


print(check_classifiers_train("dummy", BaseDummy()))
print("memmap:", check_classifiers_train("dummy", BaseDummy(), readonly_memmap=True))
print("float32:", check_classifiers_train("dummy", BaseDummy(), X_dtype="float32"))


class Pairwise(BaseDummy):
    def __sklearn_tags__(self):
        t = super().__sklearn_tags__()
        t.input_tags.pairwise = True
