"""Tests for :func:`sklearn.utils.estimator_checks.check_classifiers_train`.

The check under test is a meta-test: it inspects a *classifier* and raises an
``AssertionError`` (or a :class:`ValueError` bubbling up from the estimator)
whenever the classifier violates the scikit-learn API contract.

The tests below therefore rely on two families of controllable test doubles:

* :class:`_CentroidClassifier` and its subclasses: a "reasonable" nearest
  centroid classifier that behaves, by default, exactly as the check expects
  (``fit``/``predict``/``decision_function``/``predict_proba``/
  ``predict_log_proba`` are all mutually consistent).  Slight breakages are
  introduced in subclasses to exercise each assertion of the check.
* :class:`_MemorizingClassifier`: a predict-only classifier whose training
  accuracy is fully controlled, which makes the ``accuracy > 0.83`` assertion
  testable exactly at its boundary.
"""

import numpy as np
import pytest

from sklearn.base import BaseEstimator, ClassifierMixin
from sklearn.linear_model import LogisticRegression, RidgeClassifier
from sklearn.neighbors import KNeighborsClassifier
from sklearn.utils.estimator_checks import check_classifiers_train

# Messages produced by ``check_classifiers_train`` itself.  They are used to
# make sure the check fails for the *expected* reason.
FIT_MSG = (
    "does not raise an error when incorrect/malformed input data for fit is "
    "passed"
)


def _features_msg(where):
    return (
        "does not raise an error when the number of features in "
        f"{where} is different from the number of features in fit."
    )


def _pairwise_msg(where):
    return (
        "does not raise an error when shape of X in  "
        f"{where} is not equal to (n_test_samples, n_training_samples)"
    )


class _CentroidClassifier(ClassifierMixin, BaseEstimator):
    """Nearest centroid classifier, consistent with the scikit-learn API."""

    def __init__(self, random_state=None):
        self.random_state = random_state

    # -- fitting ---------------------------------------------------------
    def fit(self, X, y, sample_weight=None):
        X = np.asarray(X, dtype=np.float64)
        y = np.asarray(y)
        if X.ndim != 2:
            raise ValueError("X is expected to be 2-dimensional")
        if X.shape[0] != y.shape[0]:
            raise ValueError(
                "Found input variables with inconsistent numbers of samples: "
                f"[{X.shape[0]}, {y.shape[0]}]"
            )
        self.classes_ = np.unique(y)
        self.n_features_in_ = X.shape[1]
        self._centroids_ = np.stack([X[y == c].mean(axis=0) for c in self.classes_])
        return self

    # -- helpers ---------------------------------------------------------
    def _validate_X(self, X):
        X = np.asarray(X, dtype=np.float64)
        if X.ndim != 2:
            raise ValueError("X is expected to be 2-dimensional")
        if X.shape[1] != self.n_features_in_:
            raise ValueError(
                f"X has {X.shape[1]} features, but {type(self).__name__} is "
                f"expecting {self.n_features_in_} features as input."
            )
        return X

    def _scores(self, X):
        """Negative squared distances to the centroids, shape (n_samples, n_classes)."""
        X = self._validate_X(X)
        return -((X[:, None, :] - self._centroids_[None, :, :]) ** 2).sum(axis=2)

    # -- prediction ------------------------------------------------------
    def decision_function(self, X):
        scores = self._scores(X)
        if self.classes_.size == 2:
            return scores[:, 1] - scores[:, 0]
        return scores

    def predict(self, X):
        scores = self._scores(X)
        return self.classes_[np.argmax(scores, axis=1)]

    def predict_proba(self, X):
        scores = self._scores(X)
        scores = scores - scores.max(axis=1, keepdims=True)
        exp = np.exp(scores)
        return exp / exp.sum(axis=1, keepdims=True)

    def predict_log_proba(self, X):
        return np.log(self.predict_proba(X))


class _MemorizingClassifier(ClassifierMixin, BaseEstimator):
    """Predict-only classifier whose training accuracy is fully controlled.

    ``predict`` replays the training labels, but the first
    ``round(wrong_fraction * n_samples)`` predictions are replaced by another
    class, so that the training accuracy is ``1 - wrong_fraction``.
    """

    def __init__(self, wrong_fraction=0.0, random_state=None):
        self.wrong_fraction = wrong_fraction
        self.random_state = random_state

    def fit(self, X, y, sample_weight=None):
        X = np.asarray(X, dtype=np.float64)
        y = np.asarray(y)
        if X.ndim != 2:
            raise ValueError("X is expected to be 2-dimensional")
        if X.shape[0] != y.shape[0]:
            raise ValueError(
                "Found input variables with inconsistent numbers of samples: "
                f"[{X.shape[0]}, {y.shape[0]}]"
            )
        self.classes_ = np.unique(y)
        self.n_features_in_ = X.shape[1]
        self._y_train = y.copy()
        return self

    def _validate_X(self, X):
        X = np.asarray(X, dtype=np.float64)
        if X.ndim != 2:
            raise ValueError("X is expected to be 2-dimensional")
        if X.shape[1] != self.n_features_in_:
            raise ValueError(
                f"X has {X.shape[1]} features, but {type(self).__name__} is "
                f"expecting {self.n_features_in_} features as input."
            )
        return X

    def predict(self, X):
        self._validate_X(X)
        y_pred = self._y_train.copy()
        n_wrong = int(round(self.wrong_fraction * y_pred.size))
        if n_wrong:
            positions = np.searchsorted(self.classes_, y_pred[:n_wrong])
            y_pred[:n_wrong] = self.classes_[(positions + 1) % self.classes_.size]
        return y_pred


def _recording_classifier(records):
    """Build a ``_CentroidClassifier`` subclass recording what ``fit`` receives."""

    class _RecordingClassifier(_CentroidClassifier):
        def fit(self, X, y, sample_weight=None):
            X = np.asarray(X)
            y = np.asarray(y)
            records.append(
                {
                    "dtype": X.dtype,
                    "writeable": bool(X.flags.writeable),
                    "shape": X.shape,
                    "n_classes": np.unique(y).size,
                }
            )
            return super().fit(X, y)

    return _RecordingClassifier


# ---------------------------------------------------------------------------
# Normal behaviour
# ---------------------------------------------------------------------------


def test_real_classifier_passes_and_returns_none():
    """A well behaved classifier must make the check pass silently."""
    assert check_classifiers_train("LogisticRegression", LogisticRegression()) is None


def test_real_classifier_without_decision_function_passes():
    """Classifiers lacking ``decision_function`` must be accepted."""
    assert check_classifiers_train("KNeighborsClassifier", KNeighborsClassifier()) is None


def test_real_classifier_without_predict_proba_passes():
    """Classifiers lacking ``predict_proba`` must be accepted."""
    assert check_classifiers_train("RidgeClassifier", RidgeClassifier()) is None


def test_consistent_nearest_centroid_classifier_passes():
    """Our reference test double exercises every branch of the check."""
    assert check_classifiers_train("Centroid", _CentroidClassifier()) is None


@pytest.mark.parametrize("estimator", [LogisticRegression(), _CentroidClassifier()])
def test_readonly_memmap_is_supported(estimator):
    """``readonly_memmap=True`` must run the checks on read-only memory maps."""
    records = []
    estimator_cls = _recording_classifier(records)
    assert (
        check_classifiers_train("Mapped", estimator_cls(), readonly_memmap=True) is None
    )
    # One problem (binary) and one multi-class problem, each fitted three times.
    assert len(records) == 6
    # The in-memory (memmap backed) arrays must not be writeable ...
    assert [record["writeable"] for record in records] == [
        False,
        False,
        True,
        False,
        False,
        True,
    ]
    # ... while the plain lists passed to ``fit(X.tolist(), y.tolist())`` are.
    assert all(not np.issubdtype(r["dtype"], np.integer) for r in records)


@pytest.mark.parametrize(
    "X_dtype, expected_itemsize", [("float64", 8), ("float32", 4)]
)
def test_X_dtype_is_forwarded_to_fit(X_dtype, expected_itemsize):
    """``X_dtype`` controls the dtype of the data handed over to the estimator."""
    records = []
    classifier_cls = _recording_classifier(records)
    assert check_classifiers_train("Typed", classifier_cls(), X_dtype=X_dtype) is None
    assert len(records) == 6
    # Every fit but the list based one receives the requested dtype.
    for record in records[::3]:
        assert record["dtype"] == np.dtype(X_dtype)
    assert records[0]["dtype"].itemsize == expected_itemsize


def test_default_X_dtype_is_float64():
    records = []
    classifier_cls = _recording_classifier(records)
    check_classifiers_train("Default", classifier_cls())
    assert records[0]["dtype"] == np.dtype("float64")


def test_multiclass_tag_true_runs_binary_and_multiclass_problems():
    """By default the check runs a binary *and* a multi-class problem."""
    records = []
    classifier_cls = _recording_classifier(records)
    assert check_classifiers_train("MultiClass", classifier_cls()) is None
    assert sorted({record["n_classes"] for record in records}) == [2, 3]
    # First problem is the binary one (labels 0 and 1 only).
    assert records[0]["n_classes"] == 2
    assert records[0]["shape"][0] == 200
    assert records[3]["n_classes"] == 3
    assert records[3]["shape"][0] == 300


def test_multiclass_tag_false_only_runs_binary_problem():
    """With ``multi_class=False`` the multi-class problem is skipped."""

    class _BinaryOnlyClassifier(_CentroidClassifier):
        def __sklearn_tags__(self):
            tags = super().__sklearn_tags__()
            tags.classifier_tags.multi_class = False
            return tags

    records = []
    classifier_cls = _recording_classifier(records)
    assert check_classifiers_train("BinaryOnly", classifier_cls()) is None
    assert {record["n_classes"] for record in records} == {2}
    assert {record["shape"][0] for record in records} == {200}


def test_pairwise_tag_uses_kernel_matrix():
    """With ``input_tags.pairwise`` the check passes precomputed kernel matrices."""

    class _PairwiseClassifier(_CentroidClassifier):
        def __sklearn_tags__(self):
            tags = super().__sklearn_tags__()
            tags.input_tags.pairwise = True
            return tags

    records = []
    classifier_cls = _recording_classifier(records)
    assert check_classifiers_train("Pairwise", classifier_cls()) is None
    for record in records:
        n_rows, n_cols = record["shape"]
        assert n_rows == n_cols, "a square kernel matrix should be passed to fit"
    assert sorted({record["shape"][0] for record in records}) == [200, 300]


def test_binary_decision_function_may_be_column_vector():
    """With ``single_output=False`` a binary ``decision_function`` has shape (n, 1)."""

    class _ColumnDecisionClassifier(_CentroidClassifier):
        def decision_function(self, X):
            decision = super().decision_function(X)
            return decision.reshape(-1, 1) if decision.ndim == 1 else decision

        def __sklearn_tags__(self):
            tags = super().__sklearn_tags__()
            tags.target_tags.single_output = False
            return tags

    assert check_classifiers_train("ColumnDecision", _ColumnDecisionClassifier()) is None


def test_not_implemented_decision_function_is_ignored():
    """``NotImplementedError`` raised by ``decision_function`` must be tolerated."""

    class _NoDecisionFunction(_CentroidClassifier):
        def decision_function(self, X):
            raise NotImplementedError("not available")

    assert check_classifiers_train("NoDecision", _NoDecisionFunction()) is None


def test_poor_score_tag_allows_low_accuracy():
    """Classifiers tagged ``poor_score`` are not required to reach 0.83 accuracy."""

    class _PoorScoreClassifier(_MemorizingClassifier):
        def __sklearn_tags__(self):
            tags = super().__sklearn_tags__()
            tags.classifier_tags.poor_score = True
            return tags

    # 50% training accuracy is accepted thanks to the ``poor_score`` tag.
    assert (
        check_classifiers_train("PoorScore", _PoorScoreClassifier(wrong_fraction=0.5))
        is None
    )


def test_accuracy_slightly_above_threshold_passes():
    """An accuracy of ~0.84 is accepted by the ``accuracy > 0.83`` assertion."""
    assert (
        check_classifiers_train(
            "GoodEnough", _MemorizingClassifier(wrong_fraction=0.16)
        )
        is None
    )


def test_no_validation_tag_skips_malformed_input_checks():
    """Classifiers tagged ``no_validation`` are not checked for input validation."""

    class _LenientClassifier(_CentroidClassifier):
        def __init__(self, no_validation=False, random_state=None):
            self.no_validation = no_validation
            self.random_state = random_state

        def __sklearn_tags__(self):
            tags = super().__sklearn_tags__()
            tags.no_validation = self.no_validation
            return tags

        def predict(self, X):
            # Silently reshapes the input instead of validating its shape.
            X = np.asarray(X, dtype=np.float64).reshape(-1, self.n_features_in_)
            scores = -((X[:, None, :] - self._centroids_[None, :, :]) ** 2).sum(axis=2)
            return self.classes_[np.argmax(scores, axis=1)]

    # Without the tag the missing validation is reported ...
    with pytest.raises(AssertionError, match=_features_msg("predict")):
        check_classifiers_train("Lenient", _LenientClassifier(no_validation=False))
    # ... but it is skipped when the estimator declares ``no_validation``.
    assert check_classifiers_train("Lenient", _LenientClassifier(no_validation=True)) is None


# ---------------------------------------------------------------------------
# Invalid estimators: the check must report them
# ---------------------------------------------------------------------------


def test_accuracy_exactly_at_threshold_is_rejected():
    """``accuracy > 0.83`` is a strict inequality: 0.83 exactly must fail."""
    # ``round(0.17 * 200) == 34`` -> accuracy is exactly 166 / 200 == 0.83.
    with pytest.raises(AssertionError):
        check_classifiers_train(
