def test_consistent_nearest_centroid_classifier_passes():
    """Our reference test double exercises every branch of the check."""
    assert check_classifiers_train("Centroid", _CentroidClassifier()) is None


@pytest.mark.parametrize("estimator", [LogisticRegression(), _CentroidClassifier()])
def test_readonly_memmap_is_supported(estimator):
    """``readonly_memmap=True`` must run the checks on read-only memory maps."""
    records = []
    estimator_cls = _recording_classifier(records)
    assert (
        check_classifiers_train("Mapped", estimator_cls(), readonly_memmap=True) is None
    )
    # One problem (binary) and one multi-class problem, each fitted three times.
    assert len(records) == 6
    # The in-memory (memmap backed) arrays must not be writeable ...
    assert [record["writeable"] for record in records] == [
        False,
        False,
        True,
        False,
        False,
        True,
    ]
    # ... while the plain lists passed to ``fit(X.tolist(), y.tolist())`` are.
    assert all(not np.issubdtype(r["dtype"], np.integer) for r in records)


