import test_check_classifiers_train as t
from sklearn.utils.estimator_checks import check_classifiers_train

class ColumnPredict(t._CentroidClassifier):
    def predict(self, X):
        return super().predict(X).reshape(-1, 1)

class NoClasses(t._CentroidClassifier):
    def fit(self, X, y, sample_weight=None):
        X = np.asarray(X, dtype=np.float64)
        if X.shape[0] != np.asarray(y).shape[0]:
            raise ValueError("inconsistent")
        self.n_features_in_ = X.shape[1]
        self._centroids_ = np.zeros((1, self.n_features_in_))
        return self

class Flipped(t._CentroidClassifier):
    def decision_function(self, X):
        return -super().decision_function(X)

class ColDecision(t._CentroidClassifier):
    def decision_function(self, X):
        d = super().decision_function(X)
        return d.reshape(-1, 1) if d.ndim == 1 else d

class OneCol(t._CentroidClassifier):
    def predict_proba(self, X):
        return super().predict_proba(X)[:, :1]

class Unnorm(t._CentroidClassifier):
    def predict_proba(self, X):
        return super().predict_proba(X) * 0.5

class Inv(t._CentroidClassifier):
    def predict_proba(self, X):
        return super().predict_proba(X)[:, ::-1]

class LogScale(t._CentroidClassifier):
    def predict_log_proba(self, X):
        return np.log(self.predict_proba(X)) + 1000.0

class LogOrder(t._CentroidClassifier):
    def predict_log_proba(self, X):
        return np.log(self.predict_proba(X))[:, ::-1]

for cls in [ColumnPredict, NoClasses, Flipped, ColDecision, OneCol, Unnorm, Inv, LogScale, LogOrder]:
    try:
        check_classifiers_train("X", cls())
    except AssertionError as e:
        tb = traceback.extract_tb(sys.exc_info()[2])
        last = [f for f in tb if f.filename.endswith("estimator_checks.py")][-1]
        print(f"{cls.__name__}: line {last.lineno}: {last.line}")
    else:
        print(f"{cls.__name__}: NO ERROR")
EOF"}

